mapper.select:
select bb.BOOKSET_ID booksetId, bb.BALANCE_DATE balanceDate, bb.SUBJECT_NO subjectNo, rpi.PROD_NAME prodName, bb.O_CCY oCcy, bb.O_AMT oAmt, bb.TDY_O_D_AMT tdyODAmt, bb.STATUS status, bb.ERRORMSG errormsg, bb.UPDATE_TIME updateTime, bb.UPDATE_USER updateUser from BOK_BALANCE bb left join V_REP_PROD_INFO rpi on bb.BOOKSET_ID = rpi.PROD_ID
AND bb.BOOKSET_ID in
#{item}
AND bb.SUBJECT_NO in
#{item}
AND bb.STATUS=#{status}
AND BALANCE_DATE >= TO_DATE(#{balanceDateStart},'YYYY-MM-DD')
AND BALANCE_DATE <= TO_DATE(#{balanceDateEnd},'YYYY-MM-DD')
and ((bb.SUBJECT_NO in ('6605', '6407', '220701') and bb.tdy_o_d_amt is not null) or (bb.SUBJECT_NO not in ('6605', '6407', '220701') and not exists (select 1 from dual where instr(bb.SUBJECT_NO, '6605') > 0) and not exists (select 1 from dual where instr(bb.SUBJECT_NO, '6407') > 0) and not exists (select 1 from dual where instr(bb.SUBJECT_NO, '220701') > 0) ))
order by NVL(bb.UPDATE_TIME,bb.CREATE_TIME) desc

mapper.delete:
update BOK_BALANCE set STATUS = 'D',UPDATE_USER=#{updateUser,jdbcType=VARCHAR},UPDATE_TIME=#{updateTime,jdbcType=TIMESTAMP}
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and BALANCE_DATE = #{balanceDate,jdbcType=DATE}
and SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}

